INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-district-command-escort', 'government', 10, 'District Command Escort', '구 부대 지휘 호위대', 'commander', 'command', 3, 'Assembly Member''s Guard Hall', '국회의원 근위청', 1000, 250, 8, NULL, 12, 90, 34, 38, 36, 50, NULL, NULL, NULL, 33, 68, '["roll-call"]', '["free-city-guard-share-pole-crews","arc-house-levy-hooks","free-city-crew-net-teams"]', 'Short clubs and pistols with a counted clip. The runner carries the operations order, which bears one stamp only, the commander''s, together with signal flags and a hand radio for the tunnel talk-line.', '짧은 곤봉과 센 만큼만 받은 탄창이 든 권총을 찬다. 전령은 지휘관의 도장 하나만 찍힌 작전 명령서와 신호기, 말줄에 붙이는 손 무전기를 맡는다.', 'Three layers: a pre-blackout camouflage winter suit cut down and re-quilted, felt boots and a navy armband. Rank insignia on the collar; the service-number token hangs beside the registry token.', '세 겹이다. 대정전 전의 얼룩무늬 방한복을 줄여 다시 누빈 옷에 펠트 장화를 신고 남색 완장을 두른다. 깃에 계급장을 달고, 군번 증표를 등재 증표 옆에 함께 건다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-assembly-members-sworn-retinue', 'government', 20, 'Assembly Member''s Sworn Retinue', '국회의원 근위 수행대', 'commander', 'champion', 4, 'Assembly Member''s Guard Hall', '국회의원 근위청', 1900, 475, 4, NULL, 10, 110, 52, 52, 55, 85, NULL, NULL, NULL, 33, 85, '["thin-clad","last-to-leave"]', '["free-city-contract-shield-company","arc-house-shield-bearers","arc-field-mechanics"]', 'Heavy fighting knives, a plate-backed breast piece under the coat and a sidearm with a counted clip. They are kin and sworn people of the Member''s house, trained to stand beside a champion in a duel.', '묵직한 전투용 단검과 외투 안의 흉갑판, 센 만큼만 받은 탄창이 든 권총을 갖춘다. 국회의원 집안의 친족과 맹세한 사람들로, 결투하는 투사 곁을 지키도록 훈련받는다.', 'Two layers: a fitted dark navy coat with a fur collar over a short jacket, and buttons cut with the seal of the Member''s house. Almost nothing is patched.', '두 겹이다. 짧은 웃옷 위에 털 깃을 단 짙은 남색 외투를 몸에 맞춰 입고, 국회의원 집안의 인장을 새긴 단추를 단다. 기운 자리가 거의 없다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-conscript-spears', 'government', 30, 'Conscript Spears', '징집 창병', 'infantry', 'line', 1, 'Levy Ledger Office', '징발 장부소', 220, 55, NULL, NULL, 60, 68, 18, 32, 24, 10, NULL, NULL, NULL, 30, 40, '["ledger-levy","charge-breaker"]', '["free-city-rail-trolley-raiders","arc-house-sled-raiders","free-city-edge-sled-scouts"]', 'Long spears cut from rail stock and scaffold pipe, a wooden shield faced with sheet metal, and the registry token on a cord. They are nineteen-year-olds in their eighteen months of service.', '레일과 비계 관을 잘라 만든 긴 창, 얇은 쇠판을 댄 나무 방패, 끈에 꿴 등재 증표를 든다. 열아홉 살에 불려 와 18개월을 복무하는 사람들이다.', 'Five layers: quilted cotton-padded clothes, over-trousers, felt boots, an ear-flap cap and a face cover. Patched everywhere, with a navy armband sewn on crooked.', '다섯 겹이다. 누빔 솜옷과 덧바지, 펠트 장화, 귀덮개 모자, 얼굴 가리개를 입는다. 곳곳을 기웠고, 남색 완장을 비뚤게 꿰매 달았다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-conscript-pick-squads', 'government', 40, 'Conscript Pick Squads', '징집 곡괭이조', 'infantry', 'shock', 1, 'Levy Ledger Office', '징발 장부소', 240, 60, NULL, NULL, 40, 70, 26, 20, 36, 8, NULL, NULL, NULL, 32, 38, '["ledger-levy","tunnel-fighter"]', '["free-city-station-air-rifle-guards","arc-house-crossbow-skirmishers","free-city-crew-net-teams"]', 'Picks and short-handled shovels from the snow-clearing stores, used on ice and on people alike. No firearms: they fight on platform levels, where powder guns are not fired.', '눈 치우기 창고에서 꺼낸 곡괭이와 자루 짧은 삽을 얼음에도 사람에게도 쓴다. 총은 없다. 화약 총을 쏘지 않는 승강장 층에서 싸우기 때문이다.', 'Four layers: quilted clothes, a padded vest, felt boots and an ear-flap cap, worn mostly underground. Knees and elbows are padded with cut-up old fabric.', '네 겹이다. 주로 땅 밑에서 지내므로 누빔옷과 솜 조끼, 펠트 장화, 귀덮개 모자를 입는다. 무릎과 팔꿈치에 옛 천을 잘라 덧댔다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-reserve-club-lines', 'government', 50, 'Reserve Club Lines', '예비군 몽둥이줄', 'infantry', 'line', 1, 'Levy Ledger Office', '징발 장부소', 180, 45, NULL, NULL, 60, 64, 16, 26, 20, 5, NULL, NULL, NULL, 30, 36, '["ledger-levy"]', '["free-city-station-air-rifle-guards","arc-house-levy-rifles"]', 'Clubs and iron bars handed out at the district office, and nothing else. Reservists up to the age of forty are called in a crisis to fill a broken line.', '구청에서 내준 몽둥이와 쇠막대뿐이다. 마흔 살까지의 예비군이 위기 때 불려 와 무너진 줄을 메운다.', 'Five layers of whatever the household had: work quilts, a grey or orange vest from their trade, felt boots. Only the navy armband handed out at muster is the same.', '다섯 겹이고, 집에 있던 것을 그대로 입는다. 작업 누빔옷에 직종의 회색이나 주황 조끼, 펠트 장화다. 소집 때 받은 남색 완장만 같다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-checkpoint-shield-line', 'government', 60, 'Checkpoint Shield Line', '검문소 방패열', 'infantry', 'line', 2, 'Ledger Drill Yard', '장부 연병장', 560, 140, NULL, NULL, 40, 80, 24, 44, 24, 40, NULL, NULL, NULL, 28, 54, '["shield-line","tunnel-fighter"]', '["free-city-brass-counting-riflemen","arc-house-levy-rifles","free-city-passage-marksmen"]', 'Tall shields made from old station doors, short spears and batons. They hold the north mouths of the three under-river tunnels, and they check the token before the gun.', '옛 역 출입문으로 만든 큰 방패와 짧은 창, 경봉을 든다. 세 강 밑 터널의 북쪽 입구를 지키며, 총보다 증표를 먼저 확인한다.', 'Three layers: a quilted coat over a padded vest, rubber-soled boots and a navy armband. A checkpoint number is painted on the shield and the helmet.', '세 겹이다. 누빔 조끼 위에 누빔 외투를 입고 고무 밑창 장화를 신으며 남색 완장을 두른다. 방패와 철모에 검문소 번호를 칠했다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-district-bayonet-line', 'government', 70, 'District Bayonet Line', '구 부대 총검열', 'infantry', 'line', 2, 'Ledger Drill Yard', '장부 연병장', 540, 135, NULL, NULL, 50, 72, 26, 36, 28, 22, NULL, NULL, NULL, 31, 52, '["charge-breaker"]', '["free-city-flywheel-trolley-shock-crews","arc-house-sled-raiders","arc-house-ski-scouts"]', 'Rifles carried unloaded with fixed bayonets; the rounds stay in the company store until an officer signs them out. Steel helmets from the old reserve armouries.', '총검을 꽂은 소총을 탄 없이 든다. 탄은 장교가 서명해 내줄 때까지 중대 창고에 있다. 옛 예비군 무기고에서 나온 철모를 쓴다.', 'Four layers: a cut-down camouflage winter suit over quilts, puttees over felt boots and an ear-flap cap under the helmet. A navy armband with the district''s number.', '네 겹이다. 누빔옷 위에 줄인 얼룩무늬 방한복을 입고, 펠트 장화 위에 각반을 감고, 철모 밑에 귀덮개 모자를 쓴다. 구 번호를 적은 남색 완장을 두른다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-exit-breaking-squad', 'government', 80, 'Exit-Breaking Squad', '출입구 따기조', 'infantry', 'breacher', 2, 'Ledger Drill Yard', '장부 연병장', 600, 150, NULL, NULL, 24, 82, 30, 26, 46, 30, NULL, NULL, NULL, 31, 54, '["breach-charge","tunnel-fighter"]', '["free-city-gate-opening-crews","arc-shelter-aid-crews","free-city-crew-net-teams","free-city-jamming-teams"]', 'Sledgehammers, crowbars and cutting bars for exit-shaft hatches and barricades. A storming order is needed before they take a door, and it carries one stamp.', '출입구 굴의 덮개와 방벽을 여는 큰 망치, 지렛대, 절단 막대를 든다. 문 하나를 따기 전에 도장 하나가 찍힌 강습 명령서가 있어야 한다.', 'Three layers: a short quilted coat, leather aprons over the thighs and thick gloves. A navy band across the helmet so the line behind can see them.', '세 겹이다. 짧은 누빔 외투에 넓적다리를 덮는 가죽 앞치마, 두꺼운 장갑을 낀다. 뒤 줄이 알아보도록 철모에 남색 띠를 둘렀다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-pole-charge-hunters', 'government', 90, 'Pole-Charge Hunters', '장대 폭약조', 'infantry', 'anti-armour', 3, 'Ledger Drill Yard', '장부 연병장', 950, 238, 4, NULL, 20, 80, 30, 26, 58, 32, NULL, NULL, NULL, 32, 64, '["machine-hunter","plate-biter"]', '["free-city-flywheel-trolley-shock-crews","free-city-rail-trolley-raiders","arc-baptised-leg-runners"]', 'Charges packed from old shells and tied to poles, and pry bars for armour plates and rail trolleys. Each charge is written in the register before it leaves the store.', '옛 포탄에서 뽑아 다시 싼 폭약을 장대에 묶고, 장갑판과 레일 수레를 뜯는 지렛대를 든다. 폭약 하나하나가 창고를 나가기 전에 장부에 오른다.', 'Three layers: a fitted quilted coat, padded trousers and felt boots, with a navy armband. A heavy canvas satchel for charges hangs at the back.', '세 겹이다. 몸에 맞춘 누빔 외투와 솜 바지, 펠트 장화에 남색 완장을 두른다. 등에 폭약을 넣는 두꺼운 범포 자루를 멘다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-guard-hall-shield-line', 'government', 100, 'Guard Hall Shield Line', '근위청 방패열', 'infantry', 'line', 4, 'Assembly Member''s Guard Hall', '국회의원 근위청', 1500, 375, 3, NULL, 24, 100, 38, 54, 40, 80, NULL, NULL, NULL, 29, 82, '["shield-line","thin-clad","last-to-leave"]', '["free-city-passage-marksmen","arc-baptised-eye-marksmen","free-city-brass-counting-riflemen"]', 'Riveted steel shields, short swords and a breast piece under the coat. Raised at a Member''s seat station from career soldiers of the military households.', '리벳을 박은 쇠 방패와 짧은 칼, 외투 안의 흉갑판을 갖춘다. 국회의원 본역에서 군 가구의 직업 군인으로 꾸린다.', 'Two layers: a fitted navy coat over a short jacket and polished boots. Almost no patching; the household number of the military family is stitched inside the collar.', '두 겹이다. 짧은 웃옷 위에 몸에 맞춘 남색 외투를 입고 손질한 장화를 신는다. 기운 자리가 거의 없고, 깃 안쪽에 군 가구의 세대 번호를 수놓았다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-reserve-riflemen', 'government', 110, 'Reserve Riflemen', '예비군 소총반', 'missile', 'rifle', 1, 'Levy Ledger Office', '징발 장부소', 300, 75, NULL, 'ammo', 30, 66, 14, 14, 20, 8, 18, 145, 8, 33, 38, '["ledger-levy"]', '["free-city-guard-share-pole-crews","arc-house-levy-cleavers","arc-house-levy-hooks"]', 'Bolt-action rifles from the old reserve armouries and eight rounds each, written against their names. A cloth bag on the belt for brass cases; a case not returned stays on the record.', '옛 예비군 무기고의 볼트식 소총과 이름 앞으로 기재한 탄 여덟 발을 받는다. 허리에 탄피를 담는 천 주머니를 찬다. 반납하지 못한 탄피는 처분 칸에 남는다.', 'Five layers: quilted clothes, over-trousers, felt boots and an ear-flap cap, all from home. The navy armband and the cartridge pouch are the only issue items.', '다섯 겹이다. 누빔옷과 덧바지, 펠트 장화, 귀덮개 모자를 집에서 입고 온다. 지급품은 남색 완장과 탄 주머니뿐이다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-conscript-air-rifles', 'government', 120, 'Conscript Air-Rifle Squads', '징집 공기총반', 'missile', 'skirmish', 1, 'Levy Ledger Office', '징발 장부소', 190, 47, NULL, NULL, 30, 64, 12, 12, 18, 6, 10, 80, 20, 34, 40, '["ledger-levy","muscle-powered","tunnel-fighter"]', '["arc-house-levy-cleavers","free-city-digging-bench-axe-crews"]', 'Air rifles bought from Free City benches, charged with hand pumps and loaded with steel shot. They shoot where powder may not be fired, inside the platform levels.', '자유도시 작업대에서 사들인 공기총을 손 펌프로 채우고 쇠구슬을 쏜다. 화약 총을 쏘지 않는 승강장 층 안에서 쏜다.', 'Four layers: quilted clothes, a padded vest and felt boots, worn underground. A navy armband and a pump hung from the shoulder strap.', '네 겹이다. 땅 밑에서 지내므로 누빔옷과 솜 조끼, 펠트 장화를 입는다. 남색 완장을 두르고 어깨끈에 펌프를 건다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-regular-riflemen', 'government', 130, 'Regular Riflemen', '직업 소총반', 'missile', 'rifle', 2, 'Firing School', '사격 교습소', 580, 148, NULL, 'ammo', 32, 68, 16, 17, 22, 18, 24, 155, 16, 33, 56, '[]', '["free-city-contract-shield-company","arc-house-shield-bearers","free-city-contract-commanders-guard"]', 'Bolt-action rifles of the National Armed Forces and old factory rounds, each one signed out and each case returned. Career soldiers from the military households.', '국군의 볼트식 소총과 옛 공장 탄을 쓴다. 한 발마다 서명해 받고 탄피는 모두 반납한다. 군 가구에서 나온 직업 군인이다.', 'Four layers: a re-quilted camouflage winter suit, puttees, felt boots and an ear-flap cap. Rank insignia and a navy armband; the cartridge pouch is stamped with the store number.', '네 겹이다. 다시 누빈 얼룩무늬 방한복에 각반과 펠트 장화, 귀덮개 모자를 쓴다. 계급장과 남색 완장을 달고, 탄 주머니에 창고 번호가 찍혀 있다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-watchtower-marksmen', 'government', 140, 'Watchtower Marksmen', '망대 저격반', 'missile', 'marksman', 3, 'Arms Repair Works', '병기 정비창', 1050, 262, 4, 'ammo', 14, 70, 16, 18, 22, 22, 70, 220, 8, 34, 66, '["skilled-crew","quiet-step"]', '["arc-near-house-heads-guard","free-city-city-heads-command-escort","arc-baptised-duel-escort"]', 'Scoped rifles kept in the arms repair works and hand-picked old rounds. They watch the machine rim from the posts on Bukhansan, Dobongsan, Suraksan and Bulamsan, and the bridge ends below.', '병기 정비창에서 손보는 조준경 소총과 골라 둔 옛 탄을 쓴다. 북한산·도봉산·수락산·불암산의 망대에서 기계 테두리를 지켜보고, 아래로는 다리 끝을 본다.', 'Four layers for long hours on the ground: a padded white over-suit on a quilted coat, felt boots and a face cover. A navy armband is sewn under the white so it shows only when they lift an arm.', '지상에서 오래 엎드리므로 네 겹이다. 누빔 외투 위에 솜을 둔 흰 덧옷을 입고 펠트 장화와 얼굴 가리개를 쓴다. 남색 완장은 흰 덧옷 안쪽에 꿰매어 팔을 들 때만 보인다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-light-mortar-crews', 'government', 150, 'Light Mortar Crews', '경박격포조', 'missile', 'artillery', 3, 'Arms Repair Works', '병기 정비창', 1050, 262, 5, 'ammo', 12, 68, 14, 14, 20, 15, 150, 380, 10, 32, 70, '["skilled-crew"]', '["free-city-guard-share-pole-crews","arc-house-levy-hooks","free-city-contract-shield-company","arc-baptised-plate-breakers"]', 'Light mortars of the Capital Defence Command and a count of old bombs kept in the cold store above the platforms. A bomb kept in the warm levels spoils in a few years.', '수도방위사령부의 경박격포와 승강장 위 찬 창고에 둔 옛 포탄을 센 만큼 쓴다. 따뜻한 층에 둔 포탄은 몇 해 안에 상한다.', 'Three layers: a fitted quilted coat, felt boots and thick gloves for the cold tube. A navy armband and a firing table card tucked into the cap.', '세 겹이다. 몸에 맞춘 누빔 외투와 펠트 장화, 차가운 포신을 잡는 두꺼운 장갑을 낀다. 남색 완장을 두르고 모자에 사격표 쪽지를 꽂았다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-heavy-mortar-battery', 'government', 160, 'Heavy Mortar Battery', '중박격포 포대', 'missile', 'artillery', 4, 'State Gun Works', '국가 포창', 1800, 450, 3, 'ammo', 12, 70, 14, 16, 20, 20, 300, 460, 10, 28, 80, '["skilled-crew","thin-clad"]', '["arc-baptised-near-house-guard","free-city-heads-own-watch","arc-near-house-heads-guard","arc-baptised-strong-arm-squad"]', 'Heavy mortars from the old defence works in Yongsan, carried in parts on hand trolleys. Every bomb is entered in the Ministry of National Defense register before it is fired.', '용산 옛 국방 시설의 중박격포를 나눠 손수레차에 싣고 다닌다. 포탄 한 발 한 발이 쏘기 전에 국방부 장부에 오른다.', 'Two layers: a short fitted navy coat and leather gloves; the crew stays near the guns in the warm entrance halls. Rank insignia on the collar.', '두 겹이다. 조원은 대합실 쪽 포 곁에 머물며 몸에 맞춘 짧은 남색 외투에 가죽 장갑을 낀다. 깃에 계급장을 단다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-rim-ski-scouts', 'government', 170, 'Rim Ski Scouts', '테두리 스키 정찰대', 'fast', 'recon', 2, 'Ledger Drill Yard', '장부 연병장', 520, 130, NULL, NULL, 12, 90, 22, 20, 24, 10, NULL, NULL, NULL, 66, 54, '["frost-hardened","scout-deploy","quiet-step"]', '["free-city-fibre-scout-drones","free-city-bench-mortar-crews","arc-house-crossbow-skirmishers"]', 'Skis, short carbines carried unloaded, field glasses and a flare pistol. They patrol the northern mountains below the machine rim and do not go past the rim posts.', '스키와 탄을 넣지 않은 짧은 기병총, 쌍안경, 신호탄 권총을 갖춘다. 북쪽 산의 기계 테두리 아래를 돌고, 테두리 망대 너머로는 가지 않는다.', 'Six layers: quilts, over-trousers, a white over-suit, felt boots, a fur-lined hood and a face cover with snow goggles. A navy cord on the hood.', '여섯 겹이다. 누빔옷과 덧바지, 흰 덧옷, 펠트 장화, 털 안감 두건, 눈가리개가 붙은 얼굴 가리개를 입는다. 두건에 남색 끈을 단다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-bridge-end-sled-patrols', 'government', 180, 'Bridge-End Sled Patrols', '다리 끝 썰매 순찰대', 'fast', 'raider', 2, 'Ledger Drill Yard', '장부 연병장', 620, 155, NULL, NULL, 14, 95, 30, 22, 30, 15, NULL, NULL, NULL, 68, 55, '["frost-hardened","quiet-step"]', '["free-city-crew-net-teams","free-city-station-air-rifle-guards","arc-shelter-aid-crews","free-city-rail-spike-throwers"]', 'Hand-pulled sleds, short spears and hatchets. They run the north ends of the seven bridges and cut off small raids crossing on foot; they never take the sled out onto the river ice.', '손으로 끄는 썰매와 짧은 창, 손도끼를 갖춘다. 일곱 다리의 북쪽 끝을 돌며 걸어 건너오는 작은 습격을 끊는다. 썰매를 강 얼음 위로 끌고 나가지 않는다.', 'Six layers against the wind on the bridges: quilts, over-trousers, a long windproof coat, felt boots in galoshes, a fur hood and a face cover. A navy armband on the coat.', '다리 위의 바람을 견디려 여섯 겹을 입는다. 누빔옷, 덧바지, 바람막이 긴 외투, 덧신을 신은 펠트 장화, 털 두건, 얼굴 가리개다. 외투에 남색 완장을 두른다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-capital-defence-scout-drones', 'government', 190, 'Capital Defence Scout Drones', '수도방위사령부 정찰 드론조', 'drone', 'recon', 3, 'State Flight Section', '국가 비행반', 1000, 250, 3, 'cells,parts', 4, 55, 10, 6, 18, 0, NULL, NULL, NULL, 80, 62, '["radio-linked","scout-deploy"]', '["free-city-bench-mortar-crews","arc-baptised-eye-marksmen","free-city-armoured-battery-trolley"]', 'Four radio-flown drones of the Capital Defence Command, flown only on the commander''s approval. A flight lasts six to ten minutes in the cold; the batteries ride in a pouch warmed against the operator''s body.', '수도방위사령부의 전파 조종 드론 네 대로, 사령관의 결재가 있어야만 띄운다. 추위 속 한 번 비행은 6~10분이고, 전지는 조종수의 몸에 붙인 주머니에서 데운다.', 'Operators wear three layers: a quilted coat, felt boots and fingerless gloves over thin gloves. A navy armband and a flight-section badge cut from an old ministry plate.', '조종수는 세 겹이다. 누빔 외투와 펠트 장화, 얇은 장갑 위에 손가락 없는 장갑을 낀다. 남색 완장과 옛 관청 명판을 잘라 만든 비행반 표를 단다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-capital-defence-strike-drones', 'government', 200, 'Capital Defence Strike Drones', '수도방위사령부 타격 드론조', 'drone', 'strike', 4, 'State Flight Command', '국가 비행 지휘소', 1800, 450, 2, 'cells,parts', 3, 70, 10, 8, 18, 5, 160, 300, 2, 80, 78, '["fibre-guided","skilled-crew","thin-clad"]', '["free-city-armoured-gun-trolley","arc-revived-armoured-locomotive","free-city-city-heads-command-escort"]', 'Three drones guided along fibre unspooled from old tunnel cable, each carrying a charge. A drone that strikes is a circuit board lost, so they fly only where the battle turns.', '옛 터널 케이블에서 뽑은 광섬유를 풀며 날리는 드론 세 대로, 대마다 폭약을 단다. 한 번 들이받으면 회로판 하나를 잃으므로 싸움의 판이 갈리는 자리에서만 띄운다.', 'Operators wear two layers: a fitted navy coat and leather gloves. Each spool carries a numbered tag that is entered in the register.', '조종수는 두 겹이다. 몸에 맞춘 남색 외투와 가죽 장갑을 낀다. 줄 감개마다 장부에 오른 번호표가 붙어 있다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-armoured-carrier-section', 'government', 210, 'Armoured Carrier Section', '장갑 수송차반', 'war-machine', 'armour', 3, 'Arms Repair Works', '병기 정비창', 1100, 275, 4, 'fuel,parts', 2, 4200, 25, 22, 250, 100, NULL, NULL, NULL, 38, 80, '[]', '["free-city-brass-counting-riflemen","arc-house-levy-rifles","free-city-guard-share-pole-crews"]', 'Two old armoured carriers, their engines replaced with large batteries charged from the Government grid. A spare power block is carried for the run back.', '엔진을 떼고 정부 전력망으로 채우는 큰 전지를 실은 옛 장갑차 두 대다. 돌아올 길을 위해 예비 동력 덩이 하나를 싣는다.', 'Hulls painted grey-white over the old green, with the navy band and a register number on the side. The crew wears quilted coats and old tank helmets.', '옛 녹색 위에 회백색을 덧칠한 차체에 남색 띠와 장부 번호를 칠했다. 조원은 누빔 외투에 옛 전차 헬멧을 쓴다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-field-gun-battery', 'government', 220, 'Field Gun Battery', '야포 포대', 'war-machine', 'artillery', 4, 'State Gun Works', '국가 포창', 1700, 425, 3, 'ammo,fuel', 3, 3600, 10, 8, 250, 40, 330, 420, 12, 24, 100, '["skilled-crew"]', '["arc-baptised-near-house-guard","free-city-heads-own-watch","arc-house-shield-bearers"]', 'Three towed field guns drawn by battery tractors, with shells from the cold store at the War Memorial. The Government holds about three quarters of Seoul''s old rounds; the guns eat them fastest.', '전지 견인차가 끄는 견인포 세 문과 전쟁기념관 찬 창고의 포탄을 쓴다. 정부는 서울 옛 탄의 약 4분의 3을 쥐었지만, 포가 그것을 가장 빨리 먹는다.', 'Guns under white canvas with the navy band painted on the shield. The crew wears quilted coats with leather aprons against the cold breech.', '흰 범포를 덮은 포의 방패에 남색 띠를 칠했다. 조원은 누빔 외투에 차가운 포미를 막는 가죽 앞치마를 두른다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-armoured-gun-carriage', 'government', 230, 'Armoured Gun Carriage', '장갑 포차', 'war-machine', 'armour', 4, 'State Gun Works', '국가 포창', 2000, 500, 2, 'ammo,fuel', 2, 6200, 30, 28, 300, 125, 220, 260, 20, 34, 90, '["iron-dread"]', '["arc-four-part-fighters","free-city-contract-storm-company","free-city-passage-marksmen"]', 'Armoured vehicles with a gun, running on large batteries and power blocks. A full charge is a day of a station''s heat, so a carriage is sent out only on the Capital Defence commander''s stamp.', '포를 단 장갑차로, 큰 전지와 동력 덩이로 굴린다. 한 번 채우는 전기가 역 하나의 하루 난방이라, 수도방위사령관의 도장이 있어야 내보낸다.', 'Thick plate patched with welded steel from other hulls, grey-white with the navy band. The crew wears quilted coats and fur hats under old helmets.', '다른 차체에서 떼어 용접한 쇠판으로 기운 두꺼운 장갑에 회백색과 남색 띠를 칠했다. 조원은 누빔 외투에 옛 헬멧 밑으로 털모자를 쓴다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-depot-revived-tank', 'government', 240, 'Depot-Revived Tank', '차량고 복원 전차', 'war-machine', 'armour', 5, 'State Vehicle Depot', '국가 차량고', 3000, 750, 1, 'ammo,fuel', 1, 9000, 40, 40, 360, 140, 440, 300, 16, 30, 100, '["irreplaceable","iron-dread"]', '["arc-hierophant-house-guard","free-city-city-heads-command-escort","arc-baptised-near-house-guard"]', 'The one tank the State Vehicle Depot keeps running, its engine gone and its tracks turned by a battery bank. No one in Seoul can build another; the Government cannot even mend it without Free City hands.', '국가 차량고가 굴려 두는 단 한 대의 전차로, 엔진을 들어내고 전지 묶음으로 궤도를 돌린다. 서울의 누구도 다시 만들지 못하고, 정부는 자유도시의 손 없이는 고치지도 못한다.', 'Old green showing through grey-white paint, a navy band round the turret and the depot register number under the gun. The crew wears fitted navy coats.', '회백색 칠 사이로 옛 녹색이 비치고, 포탑에 남색 띠를 두르고 포신 아래에 차량고 장부 번호를 칠했다. 조원은 몸에 맞춘 남색 외투를 입는다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-aid-post-net-teams', 'government', 250, 'Aid Post Net Teams', '의무소 그물조', 'support', 'countermeasure', 2, 'Ledger Aid Post', '장부 의무소', 480, 120, NULL, NULL, 12, 66, 12, 12, 18, 12, NULL, NULL, NULL, 32, 52, '["net-casting"]', '["free-city-bench-drop-drones","free-city-relay-strike-flight","free-city-fibre-scout-drones"]', 'Throwing nets and poles, and the nets strung over exit shafts, kept by the aid post. The Government has no hands to jam radio, so it catches drones by the wings.', '던지는 그물과 장대, 의무소가 손질하는 출입구 굴 위의 그물을 맡는다. 정부에는 전파를 방해할 손이 없어 드론을 날개로 잡는다.', 'Four layers: quilted clothes, a padded vest, felt boots and an ear-flap cap. A navy armband with a white stripe for the aid post.', '네 겹이다. 누빔옷과 솜 조끼, 펠트 장화, 귀덮개 모자를 쓴다. 의무소를 뜻하는 흰 줄을 넣은 남색 완장을 두른다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-aid-post-litter-bearers', 'government', 260, 'Aid Post Litter Bearers', '의무소 들것조', 'support', 'medic', 1, 'Ledger Aid Post', '장부 의무소', 280, 70, NULL, 'medicine', 12, 64, 10, 12, 18, 8, NULL, NULL, NULL, 32, 42, '["field-dressing"]', '["free-city-fibre-scout-drones"]', 'Litters, bandage rolls, a little of the old antibiotic stock and a spare net rolled on each litter pole. Every dose given is written in the aid post book.', '들것과 붕대 두루마리, 옛 항생제 재고 조금, 들것 장대마다 말아 둔 예비 그물을 든다. 놓은 약 한 번 한 번이 의무소 장부에 오른다.', 'Five layers: quilts, over-trousers, felt boots, an ear-flap cap and a face cover, for carrying the wounded across the ground. A navy armband with a white stripe.', '다친 사람을 지고 지상을 건너므로 다섯 겹이다. 누빔옷과 덧바지, 펠트 장화, 귀덮개 모자, 얼굴 가리개를 쓰고, 흰 줄을 넣은 남색 완장을 두른다.', NULL);
